style.css:
@-moz-document domain("google.com") {
/* General body styling */
    body {
        background: #000000; /* Deep black terminal aesthetic */
        color: #33ff33; /* Monochrome green for text */
        font-family: 'Press Start 2P', monospace; /* Retro pixel font */
        margin: 0;
        padding: 0;
    }

    /* Google logo styling (Text-based Tetris vibe) */
    #hplogo {
        content: "█████ G O O G L E █████";
        display: block;
        width: 100%;
        height: 100px;
        text-align: center;
        color: #33ff33;
        font-size: 28px;
        line-height: 100px;
        text-shadow: 0 0 10px #33ff33;
    }

    /* Refined search box styling */
    .gLFyf {
        background: #000000; /* Pure black background for a terminal look */
        border: 1px solid #33ff33; /* Slim green border */
        color: #33ff33; /* Retro green text */
        font-family: 'Press Start 2P', monospace;
        font-size: 14px; /* Compact text */
        text-align: left; /* Text aligned like a command line */
        padding: 5px 8px; /* Slim padding */
        margin: 0 auto; /* Centered within the page */
        width: 50%; /* Compact width */
        box-shadow: none; /* Remove blocky shadows */
        outline: none; /* Clean focus appearance */
        transition: border-color 0.2s ease-in-out;
    }

    .gLFyf:focus {
        border-color: #ff5252; /* Subtle red border when active */
    }

    input:-webkit-autofill {
        -webkit-box-shadow: 0 0 0 30px #000000 inset !important;
        -webkit-text-fill-color: #33ff33 !important;
    }

    /* Button styling (minimalist with Soviet-like geometry) */
    .FPdoLc input {
        background: #101010; /* Dark gray */
        color: #33ff33;
        font-family: 'Press Start 2P', monospace;
        font-size: 14px;
        border: 1px solid #33ff33; /* Slim border */
        padding: 8px 16px;
        margin: 5px;
        cursor: pointer;
        text-transform: uppercase;
        transition: background 0.2s ease-in-out, color 0.2s ease-in-out;
    }

    .FPdoLc input:hover {
        background: #33ff33; /* Invert colors on hover */
        color: #000000;
    }

    /* Footer links styled for Zork-era text feel */
    #fsl a {
        color: #33ff33;
        text-decoration: none;
        font-family: 'Press Start 2P', monospace;
        font-size: 12px;
    }

    #fsl a:hover {
        text-shadow: 0px 0px 10px #33ff33;
    }

    /* Links */
    a {
        color: #33ff33;
        text-decoration: none;
        font-family: 'Press Start 2P', monospace;
    }

    a:hover {
        text-shadow: 0 0 5px #33ff33;
    }

    /* Subtle grid pattern for Tetris background */
    body:before {
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: repeating-linear-gradient(
            0deg,
            rgba(51, 255, 51, 0.1) 0px,
            rgba(51, 255, 51, 0.1) 2px,
            transparent 2px,
            transparent 20px
        ),
        repeating-linear-gradient(
            90deg,
            rgba(51, 255, 51, 0.1) 0px,
            rgba(51, 255, 51, 0.1) 2px,
            transparent 2px,
            transparent 20px
        );
        z-index: -1;
    }

    /* Hide unnecessary elements for minimalism */
    #prm, .gb_2a, #SIvCob {
        display: none !important;
    }

    /* Search result links for terminal aesthetic */
    a h3 {
        color: #33ff33 !important;
        font-family: 'Press Start 2P', monospace;
        text-decoration: none;
    }

    a h3:hover {
        text-shadow: 0px 0px 10px #33ff33;
    }

    /* Minimalist scrollbar (retro terminal touch) */
    ::-webkit-scrollbar {
        width: 8px;
        background: #000000;
    }

    ::-webkit-scrollbar-thumb {
        background: #33ff33;
        border-radius: 10px;
    }
}
